import {writeFileSync} from 'fs';
import {dirname, resolve} from 'path';
import {fileURLToPath} from 'url';
import {stops, lightTheme} from '../src/styles/color-definitions.js';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, '..');
const OUT_FILE = resolve(ROOT, 'src/styles/shared/accessible-colors.css');

function buildColorScale(colorName, values) {
  return values.map((val, i) => `  --color-${colorName}-${stops[i]}: ${val.value};`).join('\n');
}

const lines = [
  '/* Auto-generated by scripts/generate-accessible-palette.js — do not edit manually */\n:root {',
];

for (const colorScale of lightTheme.contrastColors) {
  if (!colorScale.values) continue;
  lines.push(buildColorScale(colorScale.name, colorScale.values));
}

lines.push('}\n');

writeFileSync(OUT_FILE, lines.join('\n'));
console.log(`Generated ${OUT_FILE}`);